-- Only Edge service callers can provision/read this fixed Vault configuration.
-- Keys are generated by the Edge runtime, sent as SQL bind parameters, and never
-- embedded in migration text, browser DTOs or administrative tool arguments.
create function private.push_runtime_config(p_candidate jsonb default null) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare settings jsonb; total integer;
begin
  perform pg_advisory_xact_lock(hashtextextended('paul_web_push_runtime',78));
  select count(*) into total from vault.decrypted_secrets where name='paul_web_push_runtime';
  if total>1 then raise exception 'server_unavailable'; end if;
  if total=1 then
    select decrypted_secret::jsonb into settings from vault.decrypted_secrets where name='paul_web_push_runtime';
    return settings;
  end if;
  if p_candidate is null then return null; end if;
  if jsonb_typeof(p_candidate)<>'object' or (select count(*) from jsonb_object_keys(p_candidate))<>3
    or not p_candidate ?& array['public_key','private_key','worker_secret']
    or jsonb_typeof(p_candidate->'public_key')<>'string' or jsonb_typeof(p_candidate->'private_key')<>'string'
    or jsonb_typeof(p_candidate->'worker_secret')<>'string'
    or p_candidate->>'public_key' !~ '^[A-Za-z0-9_-]{87}$'
    or p_candidate->>'private_key' !~ '^[A-Za-z0-9_-]{43}$'
    or p_candidate->>'worker_secret' !~ '^[A-Za-z0-9_-]{43}$' then raise exception 'invalid_request'; end if;
  settings:=jsonb_build_object('enabled',false,'public_key',p_candidate->>'public_key','private_key',p_candidate->>'private_key',
    'worker_secret',p_candidate->>'worker_secret','subject','https://paul-flutter-profile-test.russet-otter-8833.chatgpt.site',
    'allowed_origins',jsonb_build_array('https://paul-flutter-profile-test.russet-otter-8833.chatgpt.site','https://localhost:7436'),
    'worker_url','https://ejopxxhgozsxygvkwrfr.supabase.co/functions/v1/push-worker');
  perform vault.create_secret(new_secret:=settings::text,new_name:='paul_web_push_runtime',new_description:='Paul Web Push server runtime');
  return settings;
end;
$$;
create function private.push_runtime_enable(p_enabled boolean) returns boolean
language plpgsql security definer set search_path = '' as $$
declare settings jsonb; secret_id uuid;
begin
  if p_enabled is null then raise exception 'invalid_request'; end if;
  settings:=private.push_runtime_config(null);
  if settings is null then raise exception 'server_unavailable'; end if;
  select id into secret_id from vault.decrypted_secrets where name='paul_web_push_runtime';
  settings:=jsonb_set(settings,'{enabled}',to_jsonb(p_enabled));
  perform vault.update_secret(secret_id:=secret_id,new_secret:=settings::text);
  return p_enabled;
end;
$$;
create function public.push_server_config() returns jsonb language sql set search_path = '' as $$
  select private.push_runtime_config(null);
$$;
create function public.push_provision_config(p_candidate jsonb) returns jsonb language sql set search_path = '' as $$
  select private.push_runtime_config(p_candidate);
$$;
create function public.push_config_set_enabled(p_enabled boolean) returns boolean language sql set search_path = '' as $$
  select private.push_runtime_enable(p_enabled);
$$;
revoke all on function private.push_runtime_config(jsonb),private.push_runtime_enable(boolean),public.push_server_config(),
  public.push_provision_config(jsonb),public.push_config_set_enabled(boolean) from public,anon,authenticated;
grant execute on function private.push_runtime_config(jsonb),private.push_runtime_enable(boolean),public.push_server_config(),
  public.push_provision_config(jsonb),public.push_config_set_enabled(boolean) to service_role;
